    void move() { System.out.print("W"); }
    void start() {
        System.out.print("G");
        move();
    }
}
class Drone extends Robot {
    void move() { System.out.print("F"); }
}
class Main {
    public static void main(String[] a) {
        Robot r = new Drone();
        r.start();
        r.move();
        Robot k = new Robot();
        k.start();
    }
}

